package com.wizzadrds.theworldremembers.voice; import org.junit.jupiter.api.Test; import java.nio.file.*; import static org.junit.jupiter.api.Assertions.*; class VoiceAdapterContractTest { @Test void missingSttAudioFailsWithoutNetwork(){var a=new ProcessSpeechToTextAdapter(Path.of("missing-local-stt"));assertThrows(Exception.class,()->a.transcribe(Path.of("missing-audio.wav")));} @Test void invalidTtsTextIsRejected(){var a=new ProcessTextToSpeechAdapter(Path.of("missing-local-tts"));assertThrows(IllegalArgumentException.class,()->a.synthesize("",new VoiceProfile("es","local",VoiceTemperament.CALM,0,0,50),Path.of("out.wav")));} }
